// Maps scenario commands onto the engine API (the scenario runner is tests/scenarios.rs).
use barnacle::Game;

pub struct Adapter {
    game: Option<Game>,
}

impl Adapter {
    pub fn new() -> Adapter {
        Adapter { game: None }
    }

    pub fn run(&mut self, verb: &str, args: &str) -> String {
        match verb {
            // new <seed>
            "new" => {
                self.game = Some(Game::new(args.parse().unwrap()));
                "ok".to_string()
            }
            // do <command>: the event text, or "illegal"
            "do" => match self.game.as_mut().unwrap().apply(args) {
                Ok(ev) => ev,
                Err(_) => "illegal".to_string(),
            },
            // sorted legal commands joined by "," ("-" when there are none)
            "legal" => {
                let mut m = self.game.as_ref().unwrap().legal_moves();
                m.sort();
                if m.is_empty() {
                    "-".to_string()
                } else {
                    m.join(",")
                }
            }
            "render" => self.game.as_ref().unwrap().render(),
            // "<score0> <score1> <score2> <over>"
            "status" => {
                let g = self.game.as_ref().unwrap();
                let s = g.scores();
                format!("{} {} {} {}", s[0], s[1], s[2], if g.is_over() { "yes" } else { "no" })
            }
            _ => panic!("unknown verb {}", verb),
        }
    }
}

start.tests/scenarios.rs:
// Replays every scenario file in tests/data/ against the engine through tests/adapter/mod.rs.
// A scenario file has `# scenario <name>` headers, each followed by pairs of lines: `> verb args` (a command for the
// adapter) and `= text` (the exact reply; a newline inside a reply is written \n and a backslash \\).
mod adapter;

use std::fs;

fn esc(s: &str) -> String {
    s.replace('\\', "\\\\").replace('\n', "\\n")
}

#[test]
fn scenarios() {
    let mut files: Vec<_> = fs::read_dir("tests/data")
        .expect("tests/data")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().map_or(false, |x| x == "txt"))
        .collect();
    files.sort();
    assert!(!files.is_empty(), "no scenario files in tests/data");
    let mut failures: Vec<String> = Vec::new();
    for f in files {
        let text = fs::read_to_string(&f).unwrap();
        let fname = f.file_name().unwrap().to_string_lossy().to_string();
        let mut name = String::new();
        let mut a = adapter::Adapter::new();
        let mut pending: Option<String> = None;
        let mut idx = 0;
        let mut dead = false;
        for line in text.split('\n') {
            if let Some(rest) = line.strip_prefix("# scenario") {
                name = rest.trim().to_string();
                a = adapter::Adapter::new();
                pending = None;
                idx = 0;
                dead = false;
            } else if let Some(cmd) = line.strip_prefix("> ") {
                pending = Some(cmd.to_string());
            } else if line.starts_with('=') && pending.is_some() && !dead {
                let want = if line.len() > 2 { &line[2..] } else { "" };
                let cmd = pending.take().unwrap();
                idx += 1;
                let (verb, args) = match cmd.split_once(' ') {
                    Some((v, r)) => (v, r),
                    None => (cmd.as_str(), ""),
                };
                let got = esc(&a.run(verb, args));
                if got != want {
                    failures.push(format!("{} / {}: step {}: > {}\n  expected: {}\n  got:      {}", fname, name, idx, cmd, want, got));
                    dead = true;
                }
            }
        }
    }
    if !failures.is_empty() {
        panic!("{} scenario(s) failed:\n{}", failures.len(), failures.join("\n"));
    }
}

