    RANKS.find(card.chars().next().unwrap()).unwrap()
}

fn suit_of(card: &str) -> char {
    card.chars().nth(1).unwrap()
}

fn sort_key(card: &str) -> (usize, usize) {
    (SUITS.find(suit_of(card)).unwrap(), rank_of(card))
}

