            }
        }
        let mut g = Game {
            hands: [Vec::new(), Vec::new(), Vec::new()],
            table: Vec::new(),
            leader: 0,
            trick: 1,
            scores: [0; 3],
            state: (seed as u64) % 2147483648,
            over: false,
        };
