            g.hands[k % 3].push(card);
        }
        for h in g.hands.iter_mut() {
            h.sort_by_key(|c| sort_key(c));
        }
        g
    }

    fn next(&mut self) -> u64 {
        self.state = (self.state * 1103515245 + 12345) % 2147483648;
        self.state
    }

    fn trump(&self) -> char {
        if ROTATING_TRUMP {
            SUITS.chars().nth((self.trick - 1) % 4).unwrap()
        } else {
